/*
 * Service worker.
 *
 * Hand-written rather than generated by vite-plugin-pwa: the build here is
 * already a four-step client/SSR/prerender pipeline, and a precache manifest
 * bolted onto it would be one more thing to keep in sync for caching behaviour
 * this simple.
 *
 * Its only jobs are to make the app installable and to survive a dropped
 * connection. It is deliberately not an offline-first cache.
 *
 * The rules, in order of how much trouble each one avoids:
 *
 * 1. Never touch the API. Those responses are per-user and auth'd, and a cached
 *    one served to the wrong session, or after sign-out, is a real leak.
 *
 * 2. Navigations are network-first. Cache-first would serve a stale app shell
 *    after every deploy — the exact failure that has already looked like a bug
 *    several times in this project. The cache is a fallback for when the
 *    network is genuinely gone, not a fast path.
 *
 * 3. Built assets are cache-first, but only because Vite fingerprints them.
 *    index-a1b2c3.js can never change content under the same name, so serving
 *    it from cache forever is safe. Anything unhashed must not go in here.
 */

const VERSION = 'v1';
const SHELL = `jobpilot-shell-${VERSION}`;
const ASSETS = `jobpilot-assets-${VERSION}`;

/** Anything the app cannot start without. */
const PRECACHE = ['/', '/manifest.webmanifest', '/favicon.svg'];

self.addEventListener('install', (event) => {
  event.waitUntil(
    caches
      .open(SHELL)
      // Individually, so one 404 does not fail the whole install the way
      // addAll would.
      .then((cache) => Promise.allSettled(PRECACHE.map((url) => cache.add(url))))
  );
});

self.addEventListener('activate', (event) => {
  event.waitUntil(
    (async () => {
      const keys = await caches.keys();
      await Promise.all(
        keys
          .filter((key) => key.startsWith('jobpilot-') && key !== SHELL && key !== ASSETS)
          .map((key) => caches.delete(key))
      );
      // Take over open tabs, so a stale worker is not left serving them.
      await self.clients.claim();
    })()
  );
});

self.addEventListener('fetch', (event) => {
  const { request } = event;

  // Only GET is cacheable, and only our own origin. Cross-origin covers the
  // API worker, hirefresher.in, and anything else.
  if (request.method !== 'GET') return;

  const url = new URL(request.url);
  if (url.origin !== self.location.origin) return;

  // Rule 1: the API is never cached, and never intercepted.
  if (url.pathname.startsWith('/api/')) return;

  // Rule 2: navigations are network-first.
  if (request.mode === 'navigate') {
    event.respondWith(
      (async () => {
        try {
          const fresh = await fetch(request);
          const cache = await caches.open(SHELL);
          cache.put('/', fresh.clone());
          return fresh;
        } catch {
          // Offline. Any prerendered page is better than the browser's error
          // page, and the SPA router takes over from whichever one we have.
          const cached = (await caches.match(request)) ?? (await caches.match('/'));
          if (cached) return cached;
          throw new Error('offline and nothing cached');
        }
      })()
    );
    return;
  }

  // Rule 3: fingerprinted build output only.
  if (url.pathname.startsWith('/assets/')) {
    event.respondWith(
      (async () => {
        const cached = await caches.match(request);
        if (cached) return cached;

        const fresh = await fetch(request);
        // Opaque and error responses must not be stored — caching a 404 for a
        // hashed asset would persist the failure until the next version.
        if (fresh.ok && fresh.type === 'basic') {
          const cache = await caches.open(ASSETS);
          cache.put(request, fresh.clone());
        }
        return fresh;
      })()
    );
  }
});
